<script>
  (function () {
    var section = document.querySelector('.rm-hero-web');
    if (!section) return;

    var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    /* Entradas secuenciadas al hacer scroll */
    var elements = section.querySelectorAll('[data-animate]');
    if (!('IntersectionObserver' in window) || !elements.length) {
      elements.forEach(function (el) { el.classList.add('is-visible'); });
    } else {
      var entryObserver = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
            entryObserver.unobserve(entry.target);
          }
        });
      }, { threshold: 0.15 });
      elements.forEach(function (el) { entryObserver.observe(el); });
    }

    /* Partículas de fondo */
    var canvas = section.querySelector('.rm-hero-web__particles');
    if (canvas && !reduceMotion) {
      var ctx = canvas.getContext('2d');
      var particles = [];
      var count = 44;
      var w, h;

      function resize() {
        w = canvas.width = canvas.offsetWidth;
        h = canvas.height = canvas.offsetHeight;
      }

      function init() {
        particles = [];
        for (var i = 0; i < count; i++) {
          particles.push({
            x: Math.random() * w,
            y: Math.random() * h,
            vx: (Math.random() - 0.5) * 0.25,
            vy: (Math.random() - 0.5) * 0.25
          });
        }
      }

      function step() {
        ctx.clearRect(0, 0, w, h);
        for (var i = 0; i < particles.length; i++) {
          var p = particles[i];
          p.x += p.vx;
          p.y += p.vy;
          if (p.x < 0 || p.x > w) p.vx *= -1;
          if (p.y < 0 || p.y > h) p.vy *= -1;
        }
        for (var i = 0; i < particles.length; i++) {
          for (var j = i + 1; j < particles.length; j++) {
            var a = particles[i], b = particles[j];
            var dx = a.x - b.x, dy = a.y - b.y;
            var dist = Math.sqrt(dx * dx + dy * dy);
            if (dist < 140) {
              ctx.strokeStyle = 'rgba(58,123,213,' + (0.16 * (1 - dist / 140)) + ')';
              ctx.lineWidth = 1;
              ctx.beginPath();
              ctx.moveTo(a.x, a.y);
              ctx.lineTo(b.x, b.y);
              ctx.stroke();
            }
          }
        }
        for (var i = 0; i < particles.length; i++) {
          ctx.fillStyle = 'rgba(125,211,252,0.55)';
          ctx.beginPath();
          ctx.arc(particles[i].x, particles[i].y, 1.4, 0, Math.PI * 2);
          ctx.fill();
        }
        requestAnimationFrame(step);
      }

      resize();
      init();
      step();
      window.addEventListener('resize', function () {
        resize();
        init();
      });
    }

    /* Tarjeta 3D: inclinación con el cursor, igual que en el hero de tienda */
    var visual = section.querySelector('.rm-hero-web__visual');
    var card = section.querySelector('.rm-hero-web__card');
    if (visual && card && !reduceMotion && window.matchMedia('(hover: hover)').matches) {
      visual.addEventListener('mousemove', function (e) {
        var rect = visual.getBoundingClientRect();
        var px = (e.clientX - rect.left) / rect.width - 0.5;
        var py = (e.clientY - rect.top) / rect.height - 0.5;
        var rotateY = px * 24;
        var rotateX = py * -24;
        visual.classList.add('is-interactive');
        card.style.transform = 'rotateY(' + rotateY + 'deg) rotateX(' + rotateX + 'deg) translateZ(24px)';
      });
      visual.addEventListener('mouseleave', function () {
        visual.classList.remove('is-interactive');
        card.style.transform = '';
      });
    }

    /* Halo del CTA principal siguiendo al cursor */
    var primaryCta = section.querySelector('.rm-hero-web__cta--primary');
    if (primaryCta && window.matchMedia('(hover: hover)').matches) {
      primaryCta.addEventListener('mousemove', function (e) {
        var rect = primaryCta.getBoundingClientRect();
        primaryCta.style.setProperty('--rm-mx', (e.clientX - rect.left) + 'px');
        primaryCta.style.setProperty('--rm-my', (e.clientY - rect.top) + 'px');
      });
    }
  })();
</script>
